INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000303',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss education policy at B2","Use Bildungspolitik vocabulary","Talk about Germany''s federal education system, PISA, and education inequality"],"explanation":{"intro":"Education policy vocabulary covers Germany''s federal education system, PISA shock, and debates about education inequality at B2.","culturalNote":"Bildungspolitik: Germany: Bildungsföderalismus (education federalism — education is a state (Land) responsibility — 16 different school systems — controversial). PISA-Schock (PISA shock — 2000 study — Germany ranked low — triggered major reform debates). KMK (Kultusministerkonferenz — Standing Conference of the Ministers of Education). Key challenges: Bildungsungleichheit (education inequality — Germany has above-average link between social background and educational outcomes — OECD). Bildungsarmut (educational poverty — lacking basic skills). Bildungsbenachteiligung (disadvantage — Migrationshintergrund — immigrant background). Ganztagsschule (all-day school — expansion underway — Rechtsanspruch 2026). Inklusion (inclusive education — joint schooling for children with disabilities). PISA 2022: Germany significantly declined in mathematics, reading. Schulgebäude (school buildings — massive investment backlog). Lehrermangel (teacher shortage). Digitalisierung (digitalisation — DigitalPakt Schule — €5bn 2019). Bildungsrepublik Deutschland (Angela Merkel''s aspiration 2008)."},"examples":[{"german":"Bildungsungleichheit in Deutschland hat eine ausgeprägt strukturelle Komponente: Die Bildungschancen eines Kindes korrelieren stärker mit dem sozioökonomischen Status der Eltern als in den meisten OECD-Ländern — eine Herkunftsabhängigkeit, die früh im dreigliedrigen Schulsystem durch Übergangsempfehlungen nach der Grundschule zementiert und durch den späten systematischen Bildungsausgleich nicht ausreichend kompensiert wird.","english":"Educational inequality in Germany has a markedly structural component: a child''s educational opportunities correlate more strongly with the socioeconomic status of the parents than in most OECD countries — an origin dependency that is cemented early in the three-track school system through transition recommendations after primary school, and is not sufficiently compensated by the late systematic educational equalisation."},{"german":"Der PISA-Schock von 2000 hat die deutsche Bildungspolitik nachhaltig verändert: Was bis dahin als Selbstverständlichkeit galt — ein weltklassebildungssystem — wurde durch international vergleichende Daten in Frage gestellt, und Deutschland hat seitdem strukturelle Reformen eingeleitet: Ganztagsschulausbau, Bildungsstandards, Qualitätssicherung und Frühförderung. Die Frage ist, ob diese Maßnahmen an den strukturellen Ursachen der Herkunftsabhängigkeit ansetzen.","english":"The PISA shock of 2000 has durably changed German education policy: what had been taken for granted until then — a world-class education system — was called into question by internationally comparative data, and Germany has since initiated structural reforms: expansion of all-day schools, educational standards, quality assurance, and early childhood education. The question is whether these measures address the structural causes of origin dependency."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s PISA shock, education inequality, and federalism in education at B2."}}',
'{"items":[{"word":"die Herkunftsabhängigkeit","translation":"origin dependency","pronunciation":"dee HER-koonfs-ab-heng-ikh-kyt","example":"Bildungs-Herkunftsabhängigkeit."},{"word":"das Schulsystem","translation":"school system","pronunciation":"dahs SHOOL-züs-tem","example":"Dreigliedriges Schulsystem."},{"word":"ausgeprägten","translation":"pronounced/marked","pronunciation":"OWS-geh-präk-ten","example":"Ausgeprägte Ungleichheit."},{"word":"zementieren","translation":"to cement","pronunciation":"tse-men-TEE-ren","example":"Ungleichheit zementieren."},{"word":"kompensieren","translation":"to compensate","pronunciation":"kom-pen-ZEE-ren","example":"Bildungsdefizite kompensieren."},{"word":"der Bildungsausgleich","translation":"educational equalisation","pronunciation":"dayr BIL-doongs-ows-glykh","example":"Systematischer Bildungsausgleich."}]}',
'{"title":"Etwas gilt bis dahin als Selbstverständlichkeit — something was taken for granted until then","pattern":"etwas gilt (bis dahin) als Selbstverständlichkeit = something is (until then) taken for granted (gelten als = to be considered, to count as; Selbstverständlichkeit = something self-evident, taken for granted — self + evident + quality)","explanation":"Gelten als = to be considered, to count as (not sein = to be, but how something is regarded or perceived by others). Selbstverständlichkeit = taken-for-granted assumption (selbstverständlich = self-evident, obvious — itself + understanding + adjective → abstract noun). Was bis dahin als Selbstverständlichkeit galt = what had been taken for granted until then. The pattern marks an assumption that was unchallenged until a disruption (PISA shock, scandal, discovery). Compare: als gegeben annehmen (to take for granted — more agent-centred), für selbstverständlich halten (to consider self-evident — similar), als axiomatisch betrachten (to view as axiomatic — more formal), unangefochten gelten (to be uncontested — similar, no negation).","examples":[{"sentence":"Was bis dahin als Selbstverständlichkeit galt, wurde durch die Krise in Frage gestellt.","translation":"What had been taken for granted until then was called into question by the crisis."},{"sentence":"Dass Wachstum immer Wohlstand bedeutet, gilt nicht mehr als Selbstverständlichkeit.","translation":"That growth always means prosperity is no longer taken for granted."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Herkunftsabhängigkeit'' means?","options":["origin dependency","social background effect","family influence","heritage effect"],"correctAnswer":"origin dependency"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Educational inequality in Germany has a markedly structural component: a child''s educational opportunities correlate more strongly with the socioeconomic status of the parents than in most OECD countries — an origin dependency that is cemented early in the three-track school system through transition recommendations after primary school, and is not sufficiently compensated by the late systematic educational equalisation.","options":["Bildungsungleichheit in Deutschland hat eine ausgeprägt strukturelle Komponente: Die Bildungschancen eines Kindes korrelieren stärker mit dem sozioökonomischen Status der Eltern als in den meisten OECD-Ländern — eine Herkunftsabhängigkeit, die früh im dreigliedrigen Schulsystem durch Übergangsempfehlungen nach der Grundschule zementiert und durch den späten systematischen Bildungsausgleich nicht ausreichend kompensiert wird.","Bildungsungleichheit in Deutschland hängt stark von der sozialen Herkunft ab.","PISA zeigt: Deutschlands Schulen reproduzieren soziale Ungleichheit statt sie zu überwinden.","Bildungschancen hängen mehr vom Elternhaus ab als in vergleichbaren Ländern."],"correctAnswer":"Bildungsungleichheit in Deutschland hat eine ausgeprägt strukturelle Komponente: Die Bildungschancen eines Kindes korrelieren stärker mit dem sozioökonomischen Status der Eltern als in den meisten OECD-Ländern — eine Herkunftsabhängigkeit, die früh im dreigliedrigen Schulsystem durch Übergangsempfehlungen nach der Grundschule zementiert und durch den späten systematischen Bildungsausgleich nicht ausreichend kompensiert wird."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dass Wachstum immer Wohlstand bedeutet, gilt nicht mehr als ___.","options":["Selbstverständlichkeit","Axiom","Wahrheit","Grundsatz"],"correctAnswer":"Selbstverständlichkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What had been taken for granted until then was called into question by the crisis","wordBankItems":["Was","bis","dahin","als","Selbstverständlichkeit","galt",",","wurde","durch","die","Krise","in","Frage","gestellt","."],"correctAnswer":"Was bis dahin als Selbstverständlichkeit galt , wurde durch die Krise in Frage gestellt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zementieren'' means?","options":["to cement","to fix","to entrench","to solidify"],"correctAnswer":"to cement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000304',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss higher education policy at B2","Use Hochschulpolitik vocabulary","Talk about Germany''s free tuition, Bologna Reform, and university excellence"],"explanation":{"intro":"Higher education policy vocabulary covers Germany''s tuition-free universities, Bologna Reform, and the Excellence Initiative at B2.","culturalNote":"Hochschulpolitik: Germany: Studiengebührenfreiheit (tuition-free universities — almost all public universities — exception: Baden-Württemberg for non-EU international students). Bologna-Reform (Bologna Reform — 1999 — Bachelor/Master system — harmonisation across Europe — controversial: Verschulung (schoolification) of university). HRK (Hochschulrektorenkonferenz). Exzellenzinitiative (Excellence Initiative — 2006, 2012, 2019 — German Universities Excellence Strategy — 57 clusters of excellence — aim: world-class research hubs). Fachhochschule vs. Universität (applied vs. research university). Grundlagenforschung (basic research). Drittmittel (third-party funding — DFG, BMBF, EU). Freie Forschung. Hochschulautonomie (university autonomy). Numerus Clausus (NC — restricted admission). Studierendenwerk (student services). Wohnheim (student dormitory — shortage). BAföG (Bundesausbildungsförderungsgesetz — student financial aid — reformed 2023 — 50% grant / 50% interest-free loan). Brain drain (emigration of German researchers). Wissenschaftsrat (German Science Council)."},"examples":[{"german":"Die Exzellenzinitiative hat das deutsche Hochschulsystem tiefgreifend verändert: Statt eines egalitären Systems mit formal gleichwertigen Hochschulen hat die staatliche Förderung von Exzellenzclustern und Exzellenzuniversitäten eine Hierarchisierung eingeleitet, in der einige Universitäten — LMU München, TU München, Heidelberg, FU Berlin — internationale Spitzenforschung anziehen, während andere um Reputation und Drittmittel konkurrieren.","english":"The Excellence Initiative has profoundly changed the German higher education system: instead of an egalitarian system with formally equivalent universities, the state funding of excellence clusters and excellence universities has initiated a hierarchisation in which some universities — LMU Munich, TU Munich, Heidelberg, FU Berlin — attract international top research, while others compete for reputation and third-party funding."},{"german":"Die Bologna-Reform hat die Hochschulbildung europaweit harmonisiert und Mobilität ermöglicht, aber auch Kritik ausgelöst: Die Verschulung des Studiums durch enge Credit-Systeme, verpflichtende Kurse und kurze Regelstudienzeiten hat den Freiraum für eigenständiges Denken und die Breite der Bildung eingeschränkt — eine Sorge, die Wilhelm von Humboldts Ideal der Bildung durch Wissenschaft berührt.","english":"The Bologna Reform has harmonised university education across Europe and enabled mobility, but has also generated criticism: the ''schoolification'' of study through tight credit systems, compulsory courses, and short standard study periods has restricted the freedom for independent thinking and the breadth of education — a concern that touches Wilhelm von Humboldt''s ideal of education through science."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s Excellence Initiative, Bologna Reform, and tuition policy at B2."}}',
'{"items":[{"word":"die Hierarchisierung","translation":"hierarchisation","pronunciation":"dee hi-er-ar-khi-ZEE-roong","example":"Hierarchisierung des Hochschulsystems."},{"word":"das Exzellenzcluster","translation":"excellence cluster","pronunciation":"dahs ex-tse-LENTS-kloos-ter","example":"Exzellenzcluster fördern."},{"word":"egalitär","translation":"egalitarian","pronunciation":"eh-ga-li-TÄR","example":"Egalitäres System."},{"word":"die Verschulung","translation":"schoolification","pronunciation":"dee fer-SHOO-loong","example":"Verschulung der Hochschulen."},{"word":"die Drittmittel","translation":"third-party funding","pronunciation":"dee DRIT-mit-el","example":"Drittmittel einwerben."},{"word":"eigenständig","translation":"independent","pronunciation":"EY-gen-shten-dikh","example":"Eigenständiges Denken."}]}',
'{"title":"Etwas leitet X ein — something initiates/inaugurates X","pattern":"etwas leitet X ein = something initiates, inaugurates X (einleiten = to initiate, start — separable: leitet...ein; marks the beginning of a process, reform, or change — more formal and process-oriented than starten or beginnen)","explanation":"Einleiten = to initiate, inaugurate, set in motion (separable: leitet...ein — ein = into + leiten = to lead/guide). Etwas leitet X ein = something starts/opens X as a process. Die Exzellenzinitiative hat eine Hierarchisierung eingeleitet = the Excellence Initiative has initiated a hierarchisation. Used for policy, reform, legal, or structural processes being set in motion — often as the first step of a longer chain. Compare: einführen (to introduce — more product/measure), anstoßen (to trigger — lighter, less formal), starten (to start — more colloquial), in Gang setzen (to set in motion — similar, slightly more mechanical), initiieren (to initiate — Latinate synonym, formal).","examples":[{"sentence":"Die Regierung leitete mit dem Gesetzentwurf ein neues Kapitel der Sozialpolitik ein.","translation":"With the draft law, the government initiated a new chapter of social policy."},{"sentence":"Der Skandal hat einen Reformprozess eingeleitet, der nicht mehr aufzuhalten war.","translation":"The scandal initiated a reform process that could no longer be stopped."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Hierarchisierung'' means?","options":["hierarchisation","ranking","stratification","tiering"],"correctAnswer":"hierarchisation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Excellence Initiative has profoundly changed the German higher education system: instead of an egalitarian system with formally equivalent universities, the state funding of excellence clusters and excellence universities has initiated a hierarchisation in which some universities — LMU Munich, TU Munich, Heidelberg, FU Berlin — attract international top research, while others compete for reputation and third-party funding.","options":["Die Exzellenzinitiative hat das deutsche Hochschulsystem tiefgreifend verändert: Statt eines egalitären Systems mit formal gleichwertigen Hochschulen hat die staatliche Förderung von Exzellenzclustern und Exzellenzuniversitäten eine Hierarchisierung eingeleitet, in der einige Universitäten — LMU München, TU München, Heidelberg, FU Berlin — internationale Spitzenforschung anziehen, während andere um Reputation und Drittmittel konkurrieren.","Die Exzellenzinitiative fördert einige Eliteuniversitäten und vernachlässigt andere.","Durch staatliche Förderung entstehen Universitätshierarchien wie in den USA.","LMU, TU München und Heidelberg werden durch Exzellenzförderung zu Weltklasse-Unis."],"correctAnswer":"Die Exzellenzinitiative hat das deutsche Hochschulsystem tiefgreifend verändert: Statt eines egalitären Systems mit formal gleichwertigen Hochschulen hat die staatliche Förderung von Exzellenzclustern und Exzellenzuniversitäten eine Hierarchisierung eingeleitet, in der einige Universitäten — LMU München, TU München, Heidelberg, FU Berlin — internationale Spitzenforschung anziehen, während andere um Reputation und Drittmittel konkurrieren."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Skandal hat einen Reformprozess eingeleitet, der nicht mehr aufzuhalten ___.","options":["war","ist","wurde","sein"],"correctAnswer":"war"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: With the draft law the government initiated a new chapter of social policy","wordBankItems":["Die","Regierung","leitete","mit","dem","Gesetzentwurf","ein","neues","Kapitel","der","Sozialpolitik","ein","."],"correctAnswer":"Die Regierung leitete mit dem Gesetzentwurf ein neues Kapitel der Sozialpolitik ein ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Egalitär'' means?","options":["egalitarian","equal","equitable","equivalent"],"correctAnswer":"egalitarian"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000305',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss digitalisation of education at B2","Use Digitalisierung der Bildung vocabulary","Talk about Germany''s DigitalPakt, tablet debate, and digital skills gap"],"explanation":{"intro":"Digitalisation of education vocabulary covers Germany''s slow digital adoption in schools, DigitalPakt Schule, and the debate about digital skills at B2.","culturalNote":"Digitalisierung der Bildung: Germany: notoriously slow — ranked 27th out of 34 OECD countries in ICT in education. DigitalPakt Schule (€5bn 2019–2024 — WLAN, devices, servers). Problem: hardware without training and pedagogical concepts. Key: Lehrerfortbildung (teacher training) for digital tools — underfunded. Medienkompetenz (media literacy). Coding in schools. Corona-Pandemie: exposed digital gap (digitale Kluft) — 1.5M students without device/internet. BYOD (Bring Your Own Device) debate. Lernmanagementsysteme (LMS — Moodle, itslearning). Open Educational Resources (OER). Datenschutz (data protection — German schools ban Google Classroom — DSGVO). Kritisches Denken vs. digitale Kompetenz. Key: Computer science as school subject (Informatik als Pflichtfach — not yet mandatory in all states). AI in education (ChatGPT in classrooms — Schummeln vs. neues Lernen)."},"examples":[{"german":"Die Coronapandemie hat die digitale Kluft im deutschen Bildungssystem schonungslos offengelegt: Schülerinnen und Schüler aus einkommensschwachen Haushalten fehlten vielfach Gerät, stabile Internetverbindung und häusliche Lernbedingungen — Defizite, die in normalen Zeiten durch Präsenzunterricht überbrückt werden, in einer reinen Online-Phase aber bildungsbiografisch folgenreich werden konnten.","english":"The Corona pandemic has mercilessly exposed the digital divide in the German education system: pupils from low-income households frequently lacked devices, stable internet connections, and home learning conditions — deficits that are bridged during normal times by classroom instruction, but during a purely online phase could become consequential for educational biographies."},{"german":"Die Diskussion um digitale Bildung ist nicht auf Technologie zu reduzieren: Tablets und WLAN sind notwendige, aber nicht hinreichende Bedingungen für digitale Bildung. Die eigentliche Frage ist pädagogischer Natur — wie verändert die digitale Umgebung das Lernen, welche neuen Kompetenzen werden gebraucht und wie können kritisches Denken, Quellenprüfung und ethisches Handeln im digitalen Raum gelehrt werden.","english":"The discussion about digital education cannot be reduced to technology: tablets and WiFi are necessary, but not sufficient conditions for digital education. The actual question is pedagogical in nature — how does the digital environment change learning, what new competencies are needed, and how can critical thinking, source verification, and ethical action be taught in the digital space."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s DigitalPakt, the digital divide in schools, and media literacy at B2."}}',
'{"items":[{"word":"schonungslos","translation":"mercilessly","pronunciation":"SHO-noongs-lohs","example":"Schonungslos offenlegen."},{"word":"die Bildungsbiografie","translation":"educational biography","pronunciation":"dee BIL-doongs-bee-oh-gra-fee","example":"Bildungsbiografisch folgenreich."},{"word":"überbrücken","translation":"to bridge","pronunciation":"ü-ber-BRÜK-en","example":"Defizite überbrücken."},{"word":"notwendig aber nicht hinreichend","translation":"necessary but not sufficient","pronunciation":"not-VEN-dikh ah-ber nikht HIN-ry-khend","example":"Notwendige aber nicht hinreichende Bedingung."},{"word":"die Quellenprüfung","translation":"source verification","pronunciation":"dee KVEL-en-prü-foong","example":"Kritische Quellenprüfung."},{"word":"pädagogisch","translation":"pedagogical","pronunciation":"pä-da-GO-gish","example":"Pädagogische Frage."}]}',
'{"title":"X ist nicht auf Y zu reduzieren — X cannot be reduced to Y","pattern":"X ist nicht auf Y zu reduzieren = X cannot be reduced to Y (nicht auf Y zu reduzieren — modal passive with zu + infinitive: sein + zu + infinitive = can/must — ''nicht auf Y zu reduzieren sein'' = cannot be reduced to Y; marks that X is more complex than Y would suggest)","explanation":"Modal passive with sein + zu + infinitive: Etwas ist auf Y zu reduzieren = something can be reduced to Y (passive: Y is the reduction target). Mit Negation: Etwas ist nicht auf Y zu reduzieren = something cannot be reduced to Y. X ist nicht auf Y zu reduzieren marks that X has dimensions beyond Y — a rejection of oversimplification. Die Diskussion ist nicht auf Technologie zu reduzieren = the discussion cannot be reduced to technology. Compare: mehr als X sein (to be more than X — positive, additive), über X hinausgehen (to go beyond X — directional), X allein greift zu kurz (X alone falls short — critique of single-cause thinking), X vereinfacht (X oversimplifies — stronger, more critical).","examples":[{"sentence":"Armut ist nicht auf mangelnde Arbeitsbereitschaft zu reduzieren.","translation":"Poverty cannot be reduced to a lack of willingness to work."},{"sentence":"Demokratie ist nicht auf Wahlen zu reduzieren.","translation":"Democracy cannot be reduced to elections."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schonungslos'' means?","options":["mercilessly","ruthlessly","unsparing","harshly"],"correctAnswer":"mercilessly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Corona pandemic has mercilessly exposed the digital divide in the German education system: pupils from low-income households frequently lacked devices, stable internet connections, and home learning conditions — deficits that are bridged during normal times by classroom instruction, but during a purely online phase could become consequential for educational biographies.","options":["Die Coronapandemie hat die digitale Kluft im deutschen Bildungssystem schonungslos offengelegt: Schülerinnen und Schüler aus einkommensschwachen Haushalten fehlten vielfach Gerät, stabile Internetverbindung und häusliche Lernbedingungen — Defizite, die in normalen Zeiten durch Präsenzunterricht überbrückt werden, in einer reinen Online-Phase aber bildungsbiografisch folgenreich werden konnten.","Die Pandemie hat gezeigt, dass ärmere Schüler weniger Zugang zu digitalen Geräten haben.","Digitale Bildungsungleichheit wurde in der Pandemie sichtbar, weil Schüler zu Hause lernen mussten.","Ohne Gerät und Internet war Home-Schooling für viele Kinder nicht möglich."],"correctAnswer":"Die Coronapandemie hat die digitale Kluft im deutschen Bildungssystem schonungslos offengelegt: Schülerinnen und Schüler aus einkommensschwachen Haushalten fehlten vielfach Gerät, stabile Internetverbindung und häusliche Lernbedingungen — Defizite, die in normalen Zeiten durch Präsenzunterricht überbrückt werden, in einer reinen Online-Phase aber bildungsbiografisch folgenreich werden konnten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Armut ist nicht auf mangelnde Arbeitsbereitschaft zu ___.","options":["reduzieren","vereinfachen","beschränken","begrenzen"],"correctAnswer":"reduzieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Democracy cannot be reduced to elections","wordBankItems":["Demokratie","ist","nicht","auf","Wahlen","zu","reduzieren","."],"correctAnswer":"Demokratie ist nicht auf Wahlen zu reduzieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Quellenprüfung'' means?","options":["source verification","fact-checking","source analysis","citation check"],"correctAnswer":"source verification"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000306',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss lifelong learning at B2","Use Lebenslanges Lernen vocabulary","Talk about Germany''s adult education, continuing training, and the knowledge economy"],"explanation":{"intro":"Lifelong learning vocabulary covers Germany''s Volkshochschulen, vocational retraining, and the knowledge economy at B2.","culturalNote":"Lebenslanges Lernen: Germany: Weiterbildung (continuing education/training — one of the largest sectors). Volkshochschule (VHS — adult education centre — 900 in Germany — German courses, computer, languages, health). Key: Qualifizierungsoffensive (skills upgrading — government response to structural unemployment and AI). Kurzarbeitergeld (short-time working allowance — paid retraining during downtime — successful Pandemie tool). Umschulung (retraining — for job changers). Meister (master craftsperson qualification — highly valued). Bundesagentur für Arbeit (Federal Employment Agency — retraining funding). DGB (Deutsches Gewerkschaftsbund — trade unions — advocate for Bildungszeit/paid educational leave). Bildungszeit (paid educational leave — 5 days/year in some states). Key challenge: Fachkräftemangel (skilled labour shortage) — requires upskilling of existing workers. AI and automation: Umschulung für Industriearbeiter. MOOCs (Massive Open Online Courses). Formal vs. non-formal vs. informal learning."},"examples":[{"german":"Lebenslanges Lernen ist in der Wissensgesellschaft keine Option mehr, sondern eine strukturelle Notwendigkeit: Da Wissens- und Kompetenzanforderungen schneller veralten als Berufslebenszyklen, müssen Arbeitnehmende ihre Qualifikationen kontinuierlich erneuern — eine Anforderung, die Bildungssysteme, die historisch auf die einmalige Erstausbildung ausgerichtet waren, in ihrer Konzeption und Finanzierungslogik grundlegend in Frage stellt.","english":"Lifelong learning is no longer an option in the knowledge society, but a structural necessity: since knowledge and competence requirements become obsolete faster than working life cycles, employees must continuously renew their qualifications — a requirement that fundamentally questions education systems, which were historically oriented towards one-time initial education, in their conception and financing logic."},{"german":"Die Qualifizierungsoffensive reagiert auf eine Paradoxie des technologischen Wandels: Automatisierung und Digitalisierung schaffen neue Berufe und Tätigkeiten, vernichten aber zugleich jene Routinetätigkeiten, in denen Beschäftigte ohne höhere Qualifikationen beschäftigt sind — also jene Arbeitnehmenden, die Umschulungsangebote am meisten brauchen und gleichzeitig am wenigsten leicht in Anspruch nehmen.","english":"The skills upgrading initiative responds to a paradox of technological change: automation and digitalisation create new professions and activities, but simultaneously destroy those routine activities in which employees without higher qualifications are employed — thus precisely those workers who need retraining offers most and at the same time find them most difficult to access."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss lifelong learning, Qualifizierungsoffensive, and adult education in Germany at B2."}}',
'{"items":[{"word":"veralten","translation":"to become obsolete","pronunciation":"fer-AL-ten","example":"Qualifikationen veralten."},{"word":"die Erstausbildung","translation":"initial education/training","pronunciation":"dee ERST-ows-bil-doong","example":"Einmalige Erstausbildung."},{"word":"die Notwendigkeit","translation":"necessity","pronunciation":"dee not-VEN-dikh-kyt","example":"Strukturelle Notwendigkeit."},{"word":"in Anspruch nehmen","translation":"to access/make use of","pronunciation":"in AN-shprookh NEH-men","example":"Angebote in Anspruch nehmen."},{"word":"gleichzeitig","translation":"simultaneously","pronunciation":"GLYKH-tsy-tikh","example":"Gleichzeitig schaffen und vernichten."},{"word":"die Umschulung","translation":"retraining","pronunciation":"dee OOM-shoo-loong","example":"Umschulung für neue Berufe."}]}',
'{"title":"Etwas ist keine Option mehr, sondern eine strukturelle Notwendigkeit — something is no longer an option but a structural necessity","pattern":"etwas ist keine Option mehr, sondern eine strukturelle Notwendigkeit = something is no longer an option, but a structural necessity (nicht mehr...sondern = no longer...but; strukturell = structural — marks that something has moved from voluntary choice to unavoidable systemic requirement)","explanation":"Keine Option mehr = no longer an option (nicht mehr = no longer — temporal shift; Option = choice, voluntary). Sondern = but rather (corrective: replaces the negated element with something different). Strukturelle Notwendigkeit = structural necessity (structural = built into the system, not chosen). Lebenslanges Lernen ist keine Option mehr, sondern eine strukturelle Notwendigkeit = lifelong learning is no longer an option, but a structural necessity. Marks a transition from voluntary to obligatory, driven by structural change (not individual decision). Compare: ein Muss sein (to be a must — more colloquial), unumgänglich sein (to be unavoidable — less structural), alternativlos sein (to be without alternative — more political, often dismissive), zwingend erforderlich sein (to be absolutely required — more formal, less systemic framing).","examples":[{"sentence":"Sicherheitsaudits sind keine Option mehr, sondern eine gesetzliche Notwendigkeit.","translation":"Security audits are no longer an option, but a legal necessity."},{"sentence":"Klimaanpassung ist keine Option mehr, sondern eine strukturelle Notwendigkeit für Städte.","translation":"Climate adaptation is no longer an option, but a structural necessity for cities."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Veralten'' means?","options":["to become obsolete","to age","to expire","to decay"],"correctAnswer":"to become obsolete"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Lifelong learning is no longer an option in the knowledge society, but a structural necessity: since knowledge and competence requirements become obsolete faster than working life cycles, employees must continuously renew their qualifications — a requirement that fundamentally questions education systems, which were historically oriented towards one-time initial education, in their conception and financing logic.","options":["Lebenslanges Lernen ist in der Wissensgesellschaft keine Option mehr, sondern eine strukturelle Notwendigkeit: Da Wissens- und Kompetenzanforderungen schneller veralten als Berufslebenszyklen, müssen Arbeitnehmende ihre Qualifikationen kontinuierlich erneuern — eine Anforderung, die Bildungssysteme, die historisch auf die einmalige Erstausbildung ausgerichtet waren, in ihrer Konzeption und Finanzierungslogik grundlegend in Frage stellt.","In der Wissensgesellschaft müssen sich alle Arbeitnehmer ständig weiterbilden.","Bildungssysteme müssen sich auf lebenslanges Lernen ausrichten, nicht nur auf Erstausbildung.","Qualifikationen veralten schnell — deshalb ist kontinuierliche Weiterbildung unverzichtbar."],"correctAnswer":"Lebenslanges Lernen ist in der Wissensgesellschaft keine Option mehr, sondern eine strukturelle Notwendigkeit: Da Wissens- und Kompetenzanforderungen schneller veralten als Berufslebenszyklen, müssen Arbeitnehmende ihre Qualifikationen kontinuierlich erneuern — eine Anforderung, die Bildungssysteme, die historisch auf die einmalige Erstausbildung ausgerichtet waren, in ihrer Konzeption und Finanzierungslogik grundlegend in Frage stellt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Klimaanpassung ist keine Option mehr, sondern eine strukturelle Notwendigkeit für ___.","options":["Städte","Regionen","Länder","Gemeinden"],"correctAnswer":"Städte"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Security audits are no longer an option but a legal necessity","wordBankItems":["Sicherheitsaudits","sind","keine","Option","mehr",",","sondern","eine","gesetzliche","Notwendigkeit","."],"correctAnswer":"Sicherheitsaudits sind keine Option mehr , sondern eine gesetzliche Notwendigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Umschulung'' means?","options":["retraining","requalification","skills renewal","upskilling"],"correctAnswer":"retraining"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000307',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss elite education and equal opportunity at B2","Use Elitebildung und Chancengleichheit vocabulary","Talk about Germany''s educational elites, class reproduction, and affirmative action debates"],"explanation":{"intro":"Elite education and equal opportunity vocabulary covers Bourdieu''s cultural capital, Germany''s elite schools, and the debate over Chancengleichheit at B2.","culturalNote":"Elitebildung und Chancengleichheit: Germany: Elite schools — few explicit elite schools (unlike UK/US). Private schools (Privatschulen) — 8% of students but growing. Key: Bourdieu (Pierre Bourdieu — Reproduction in Education, 1970 — cultural capital, habitus — social class reproduced through education). Soziale Reproduktion (social reproduction). Chancengleichheit (equal opportunity) vs. Chancengerechtigkeit (equity — equal outcomes vs. equal starting conditions). Stipendien (scholarships — Begabtenförderung — 13 major foundations — Hans Böckler Stiftung, Studienstiftung des deutschen Volkes, Konrad Adenauer Stiftung). Key debate: NC and social selection — high NC makes access unequal. Eliteuniversität (elite university — Germany resists the term but has the reality post-Exzellenzinitiative). Hochbegabtentests. Privatschule debate — Verfassungsgebot gegen ein Vorbereitungsschulwesen in Art. 7 Abs. 4 GG."},"examples":[{"german":"Der französische Soziologe Pierre Bourdieu hat gezeigt, dass Bildung weniger eine Meritokratie als eine Reproduktionsmaschine sozialer Privilegien ist: Durch die Weitergabe von kulturellem Kapital — Sprachkenntnissen, kulturellen Präferenzen, Bildungserwartungen — reproduzieren privilegierte Klassen ihren Bildungsvorsprung über Generationen, auch ohne direkten Einsatz wirtschaftlichen Kapitals. Das Bildungssystem verstärkt diesen Mechanismus, indem es die kulturellen Codes der Mittel- und Oberschicht als Bildungsstandard setzt.","english":"The French sociologist Pierre Bourdieu has shown that education is less a meritocracy than a reproduction machine of social privileges: through the transmission of cultural capital — language skills, cultural preferences, educational expectations — privileged classes reproduce their educational advantage across generations, even without the direct deployment of economic capital. The education system reinforces this mechanism by setting the cultural codes of the middle and upper classes as the educational standard."},{"german":"Chancengleichheit und Chancengerechtigkeit sind nicht dasselbe: Chancengleichheit bezeichnet formale Gleichbehandlung — keine Diskriminierung, offene Zugangsrechte. Chancengerechtigkeit setzt eine Angleichung der Startbedingungen voraus: Förderung Benachteiligter bis zu dem Punkt, wo Ausgangspositionen vergleichbar sind. Die Frage, wie weit kompensatorische Förderung gehen darf und muss, markiert eine der zentralen politisch-philosophischen Konfliktlinien in der Bildungspolitik.","english":"Equal opportunity and equity are not the same thing: equal opportunity designates formal equal treatment — no discrimination, open access rights. Equity presupposes an equalisation of starting conditions: support for the disadvantaged up to the point where starting positions are comparable. The question of how far compensatory support may and must go marks one of the central political-philosophical fault lines in education policy."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Bourdieu''s cultural capital, Chancengleichheit vs. Chancengerechtigkeit, and social reproduction through education at B2."}}',
'{"items":[{"word":"die soziale Reproduktion","translation":"social reproduction","pronunciation":"dee zo-TSYAHL-eh re-pro-dook-TSYOHN","example":"Soziale Reproduktion durch Bildung."},{"word":"das kulturelle Kapital","translation":"cultural capital","pronunciation":"dahs kool-too-REL-eh ka-pi-TAHL","example":"Kulturelles Kapital weitergeben."},{"word":"die Meritokratie","translation":"meritocracy","pronunciation":"dee meh-ri-to-kra-TEE","example":"Meritokratisches Ideal."},{"word":"der Habitus","translation":"habitus","pronunciation":"dayr HA-bi-toos","example":"Bourdieu''s Konzept des Habitus."},{"word":"kompensatorisch","translation":"compensatory","pronunciation":"kom-pen-sa-TOH-rish","example":"Kompensatorische Förderung."},{"word":"die Konfliktlinie","translation":"fault line","pronunciation":"dee kon-FLIKT-li-neh","example":"Politische Konfliktlinie."}]}',
'{"title":"X setzt Y voraus — X presupposes Y","pattern":"X setzt Y voraus = X presupposes Y (voraussetzen = to presuppose, require as a precondition — separable: setzt...voraus; Y is not a consequence of X but a prerequisite — X cannot occur without Y having been established)","explanation":"Voraussetzen = to presuppose, to require as precondition (separable: setzt...voraus — voraus = ahead/before + setzen = to place; to place Y before X as necessary condition). X setzt Y voraus = X presupposes Y, X requires Y as a condition. Chancengerechtigkeit setzt eine Angleichung der Startbedingungen voraus = equity presupposes an equalisation of starting conditions. Used to reveal hidden preconditions: not just what follows from X, but what X requires before it can work. Compare: bedingen (to entail, cause — more causal), erfordern (to require — more action-demand), implizieren (to imply — weaker, more inferential), abhängen von (to depend on — more contingent), auf X basieren (to be based on X — more foundational than precondition).","examples":[{"sentence":"Demokratie setzt ein Mindestmaß an Bildung und Informiertheit voraus.","translation":"Democracy presupposes a minimum level of education and being informed."},{"sentence":"Nachhaltiger Konsum setzt veränderte Produktionssysteme voraus.","translation":"Sustainable consumption presupposes changed production systems."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Meritokratie'' means?","options":["meritocracy","ability-based society","achievement society","talent system"],"correctAnswer":"meritocracy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Equal opportunity and equity are not the same thing: equal opportunity designates formal equal treatment — no discrimination, open access rights. Equity presupposes an equalisation of starting conditions: support for the disadvantaged up to the point where starting positions are comparable. The question of how far compensatory support may and must go marks one of the central political-philosophical fault lines in education policy.","options":["Chancengleichheit und Chancengerechtigkeit sind nicht dasselbe: Chancengleichheit bezeichnet formale Gleichbehandlung — keine Diskriminierung, offene Zugangsrechte. Chancengerechtigkeit setzt eine Angleichung der Startbedingungen voraus: Förderung Benachteiligter bis zu dem Punkt, wo Ausgangspositionen vergleichbar sind. Die Frage, wie weit kompensatorische Förderung gehen darf und muss, markiert eine der zentralen politisch-philosophischen Konfliktlinien in der Bildungspolitik.","Chancengleichheit bedeutet gleiche Regeln für alle — Chancengerechtigkeit bedeutet gleiche Ergebnisse.","Formale Gleichbehandlung reicht nicht aus, wenn die Startbedingungen ungleich sind.","Kompensatorische Förderung soll Ungleichheit im Bildungssystem ausgleichen."],"correctAnswer":"Chancengleichheit und Chancengerechtigkeit sind nicht dasselbe: Chancengleichheit bezeichnet formale Gleichbehandlung — keine Diskriminierung, offene Zugangsrechte. Chancengerechtigkeit setzt eine Angleichung der Startbedingungen voraus: Förderung Benachteiligter bis zu dem Punkt, wo Ausgangspositionen vergleichbar sind. Die Frage, wie weit kompensatorische Förderung gehen darf und muss, markiert eine der zentralen politisch-philosophischen Konfliktlinien in der Bildungspolitik."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Demokratie setzt ein Mindestmaß an Bildung und Informiertheit ___.","options":["voraus","an","vor","aus"],"correctAnswer":"voraus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Sustainable consumption presupposes changed production systems","wordBankItems":["Nachhaltiger","Konsum","setzt","veränderte","Produktionssysteme","voraus","."],"correctAnswer":"Nachhaltiger Konsum setzt veränderte Produktionssysteme voraus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kompensatorisch'' means?","options":["compensatory","equalising","corrective","remedial"],"correctAnswer":"compensatory"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000308',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss school failure and educational poverty at B2","Use Schulversagen und Bildungsarmut vocabulary","Talk about Schulabbrecher, NEET youth, and Germany''s early school leaving"],"explanation":{"intro":"School failure and educational poverty vocabulary covers early school leaving, NEET youth, and Germany''s support systems at B2.","culturalNote":"Schulversagen und Bildungsarmut: Germany: Schulabbrecher (school dropouts) — about 45,000/year leave without Hauptschulabschluss — most without graduation. NEET (Not in Education, Employment or Training — 8% of 20-29 year olds in Germany). Bildungsarmut (educational poverty — lacking basic literacy/numeracy — functional illiteracy — 12% of German adults). Grundbildung (basic skills — reading, writing, arithmetic). Alphabetisierung (literacy education). Key challenges: Schulverweigerung (school refusal — Schulphobie). Jugendberufsagenturen (youth employment agencies — coordination). Jugendberufshilfe (youth vocational support). Key: migrant background and school failure — overrepresentation in Förderschulen (special schools). Übergang Schule-Beruf (school-to-work transition — Germany''s dual system historically strong but leaves some behind). Schulsozialpädagogik (school social work). Key: Rütli-Brief 2006 (teachers at Berlin school letter — overwhelmed — catalyst for discussion)."},"examples":[{"german":"Schulversagen ist selten ein individuelles Versagen: Hinter statistisch auffälligen Schulabbrüchen stehen meist mehrdimensionale Benachteiligungen — schwierige familiäre Verhältnisse, soziale Isolation, psychische Belastungen, Sprachbarrieren oder erlebte Diskriminierung. Wer Schulversagen nur als Motivationsproblem begreift, verkennt die strukturellen Ursachen und verlagert Verantwortung auf das Individuum, das die Systemausfälle kompensieren soll.","english":"School failure is rarely an individual failure: behind statistically conspicuous school dropouts are usually multi-dimensional disadvantages — difficult family circumstances, social isolation, psychological stress, language barriers, or experienced discrimination. Whoever understands school failure only as a motivation problem misunderstands the structural causes and shifts responsibility to the individual, who is supposed to compensate for the system failures."},{"german":"Funktionaler Analphabetismus ist eine stille Bildungskrise: Schätzungsweise 6,2 Millionen Erwachsene in Deutschland lesen und schreiben so unzureichend, dass sie im Alltag eingeschränkt sind — und die Dunkelziffer liegt noch höher, weil Betroffene Lesen- und Schreiben-Schwierigkeiten verbergen, um keine Stigmatisierung zu erfahren. Diese verborgene Bildungsarmut untergräbt Partizipation, Beschäftigungsfähigkeit und politische Mündigkeit.","english":"Functional illiteracy is a silent education crisis: approximately 6.2 million adults in Germany read and write so inadequately that they are restricted in everyday life — and the dark figure is even higher, because those affected conceal reading and writing difficulties to avoid experiencing stigmatisation. This hidden educational poverty undermines participation, employability, and political maturity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss school dropout, functional illiteracy, and educational poverty in Germany at B2."}}',
'{"items":[{"word":"mehrdimensional","translation":"multi-dimensional","pronunciation":"mehr-di-men-zyo-NAHL","example":"Mehrdimensionale Benachteiligung."},{"word":"verkennen","translation":"to misunderstand/misjudge","pronunciation":"fer-KEN-en","example":"Die Ursachen verkennen."},{"word":"der Schulabbruch","translation":"school dropout","pronunciation":"dayr SHOOL-ab-brookh","example":"Schulabbruch verhindern."},{"word":"die Dunkelziffer","translation":"dark figure (unknown real number)","pronunciation":"dee DOON-kel-tsif-fer","example":"Die Dunkelziffer ist hoch."},{"word":"verbergen","translation":"to conceal","pronunciation":"fer-BER-gen","example":"Schwierigkeiten verbergen."},{"word":"die Mündigkeit","translation":"maturity/autonomy","pronunciation":"dee MÜN-dikh-kyt","example":"Politische Mündigkeit."}]}',
'{"title":"Wer X als Y begreift, verkennt Z — whoever understands X as Y misunderstands Z","pattern":"Wer X als Y begreift, verkennt Z = whoever understands X as Y misunderstands Z (wer + Verb = whoever; begreifen als = to understand as, conceive of as; verkennen = to fail to recognise, misjudge — marks that a limited framing leads to misdiagnosis)","explanation":"Wer + verb = whoever (generic condemnation of a framing). Begreifen als = to conceive of as, understand as (greifen = to grasp; begreifen = to grasp conceptually; begreifen als = to conceptualise X as Y). Verkennen = to fail to recognise, to misjudge (kennen = to know; verkennen = to know wrongly, miss). Wer Schulversagen nur als Motivationsproblem begreift, verkennt die strukturellen Ursachen = whoever understands school failure only as a motivation problem misunderstands the structural causes. The pattern critiques a reductionist framing by showing what it makes invisible. Compare: zu kurz greifen (to fall short — critique of under-complexity), vereinfachen (to oversimplify), übersehen (to overlook), ignorieren (to ignore — more deliberate).","examples":[{"sentence":"Wer Armut nur als Selbstverschulden begreift, verkennt die strukturellen Ursachen sozialer Ungleichheit.","translation":"Whoever understands poverty only as self-inflicted misunderstands the structural causes of social inequality."},{"sentence":"Wer Migration nur als Problem begreift, verkennt ihren Beitrag zur Gesellschaft.","translation":"Whoever understands migration only as a problem misunderstands its contribution to society."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verkennen'' means?","options":["to misunderstand/misjudge","to ignore","to overlook","to deny"],"correctAnswer":"to misunderstand/misjudge"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"School failure is rarely an individual failure: behind statistically conspicuous school dropouts are usually multi-dimensional disadvantages — difficult family circumstances, social isolation, psychological stress, language barriers, or experienced discrimination. Whoever understands school failure only as a motivation problem misunderstands the structural causes and shifts responsibility to the individual, who is supposed to compensate for the system failures.","options":["Schulversagen ist selten ein individuelles Versagen: Hinter statistisch auffälligen Schulabbrüchen stehen meist mehrdimensionale Benachteiligungen — schwierige familiäre Verhältnisse, soziale Isolation, psychische Belastungen, Sprachbarrieren oder erlebte Diskriminierung. Wer Schulversagen nur als Motivationsproblem begreift, verkennt die strukturellen Ursachen und verlagert Verantwortung auf das Individuum, das die Systemausfälle kompensieren soll.","Schulabbruch hat oft strukturelle Ursachen: Familie, Sprache, Diskriminierung.","Schulversagen als Motivationsproblem zu sehen, ignoriert die strukturellen Hintergründe.","Schwieriges familiäres Umfeld, Sprachbarrieren und Diskriminierung führen zu Schulabbruch."],"correctAnswer":"Schulversagen ist selten ein individuelles Versagen: Hinter statistisch auffälligen Schulabbrüchen stehen meist mehrdimensionale Benachteiligungen — schwierige familiäre Verhältnisse, soziale Isolation, psychische Belastungen, Sprachbarrieren oder erlebte Diskriminierung. Wer Schulversagen nur als Motivationsproblem begreift, verkennt die strukturellen Ursachen und verlagert Verantwortung auf das Individuum, das die Systemausfälle kompensieren soll."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wer Migration nur als Problem begreift, verkennt ihren Beitrag zur ___.","options":["Gesellschaft","Wirtschaft","Nation","Gemeinschaft"],"correctAnswer":"Gesellschaft"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Whoever understands poverty only as self-inflicted misunderstands the structural causes of social inequality","wordBankItems":["Wer","Armut","nur","als","Selbstverschulden","begreift",",","verkennt","die","strukturellen","Ursachen","sozialer","Ungleichheit","."],"correctAnswer":"Wer Armut nur als Selbstverschulden begreift , verkennt die strukturellen Ursachen sozialer Ungleichheit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Dunkelziffer'' means?","options":["dark figure (unknown real number)","hidden statistic","unreported number","unknown figure"],"correctAnswer":"dark figure (unknown real number)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000309',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss vocational training and the dual system at B2","Use Berufsausbildung vocabulary","Talk about Germany''s dual training system, Azubis, and the system''s international reputation"],"explanation":{"intro":"Vocational training vocabulary covers Germany''s dual system, apprenticeships, and debates about its future at B2.","culturalNote":"Berufsausbildung und duales System: Germany: Duales Ausbildungssystem (dual training system — gold standard globally). Key: Azubi (Auszubildender — apprentice — 1.3M in Germany). Betrieb + Berufsschule (company + vocational school — 2-3 years — practical + theory). Key sectors: Handwerk (trades), Industrie (industry), Dienstleistung (services). BBiG (Berufsbildungsgesetz — Vocational Training Act — reformed 2020). Ausbildungsplatz (training place — shortage in some sectors — surplus in others). Key: shortage of Azubis in trades (Handwerk) vs. surplus of Bewerber in popular fields. DIHK (German Chamber of Commerce). HWK (Handwerkskammer). Kammerprüfungen (chamber examinations). Key export: Germany exports the dual system — Austria, Switzerland, Denmark have similar systems — developing countries adopt it. Key challenge: image problem — Hochschulstudium (university degree) seen as superior — Akademisierung (academisation) trend. Vergütung (training allowance — minimum since 2020 — €620/month minimum). Work-based learning. VET (Vocational Education and Training)."},"examples":[{"german":"Das deutsche duale Ausbildungssystem gilt international als Erfolgsmodell, weil es eine strukturelle Lösung für ein universelles Problem bietet: die Lücke zwischen akademischem Bildungsanspruch und betrieblichem Qualifikationsbedarf. Die gleichzeitige Ausbildung in Betrieb und Berufsschule vermeidet die Entkoppelung von Theorie und Praxis, erzeugt anwendbares Wissen und integriert Jugendliche direkt in den Arbeitsmarkt — was Jugendarbeitslosigkeit dauerhaft niedrig hält.","english":"The German dual training system is internationally regarded as a success model, because it offers a structural solution to a universal problem: the gap between academic educational aspiration and company qualification needs. Simultaneous training in company and vocational school avoids the decoupling of theory and practice, generates applicable knowledge, and integrates young people directly into the labour market — which keeps youth unemployment permanently low."},{"german":"Die Akademisierungsdebatte offenbart ein Werteproblem im deutschen Bildungssystem: Die gesellschaftliche Aufwertung des Hochschulstudiums gegenüber der beruflichen Ausbildung spiegelt eine Hierarchisierung wider, in der handwerkliche und praktische Kompetenzen geringer wertgeschätzt werden als akademische — eine Hierarchie, die weder den Bedarf der Wirtschaft widerspiegelt noch der Lebensqualität von Auszubildenden gerecht wird, die in ihren Berufen hochkompetent und gut bezahlt sind.","english":"The academisation debate reveals a values problem in the German education system: the social upgrading of university study relative to vocational training reflects a hierarchisation in which manual and practical competencies are valued lower than academic ones — a hierarchy that neither reflects the needs of the economy nor does justice to the quality of life of trainees who are highly competent and well paid in their professions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s dual training system, Akademisierungsdebatte, and the global reputation of German vocational training at B2."}}',
'{"items":[{"word":"das duale Ausbildungssystem","translation":"dual training system","pronunciation":"dahs doo-AH-leh OWS-bil-doongs-züs-tem","example":"Duales Ausbildungssystem."},{"word":"die Akademisierung","translation":"academisation","pronunciation":"dee a-ka-deh-mi-ZEE-roong","example":"Akademisierungsdebatte."},{"word":"die Entkopplung","translation":"decoupling","pronunciation":"dee ENT-kop-loong","example":"Entkopplung von Theorie und Praxis."},{"word":"handwerklich","translation":"manual/craft-based","pronunciation":"HANT-ver-klikh","example":"Handwerkliche Kompetenz."},{"word":"wertschätzen","translation":"to value/appreciate","pronunciation":"VERT-shet-tsen","example":"Kompetenzen wertschätzen."},{"word":"der Bedarf","translation":"need/demand","pronunciation":"dayr beh-DARF","example":"Wirtschaftlicher Bedarf."}]}',
'{"title":"Etwas spiegelt X wider — something reflects X","pattern":"etwas spiegelt X wider = something reflects X (widerspiegeln = to reflect — separable: spiegelt...wider; mirror-reflection of an underlying reality — what is visible is an image of what underlies it)","explanation":"Widerspiegeln = to reflect, mirror (separable: spiegelt...wider — wider = against/back + spiegeln = to mirror; the image is cast back). Etwas spiegelt X wider = something reflects X, is a mirror of X. Die Hierarchisierung spiegelt eine Abwertung handwerklicher Kompetenzen wider = the hierarchisation reflects a devaluation of manual competencies. The phrase marks that what is visible is an image/symptom of something deeper (values, power relations, structures). Compare: zeigen (to show — more neutral), zum Ausdruck bringen (to express — more active, intentional), manifestieren (to manifest — stronger, more philosophical), anzeigen (to indicate — more diagnostic, causal).","examples":[{"sentence":"Die Lohnunterschiede zwischen Männern und Frauen spiegeln strukturelle Ungleichheiten wider.","translation":"The wage differences between men and women reflect structural inequalities."},{"sentence":"Das Wahlergebnis spiegelt die wachsende Unzufriedenheit in der Bevölkerung wider.","translation":"The election result reflects the growing dissatisfaction in the population."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Entkopplung'' means?","options":["decoupling","disconnection","separation","disengagement"],"correctAnswer":"decoupling"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The German dual training system is internationally regarded as a success model, because it offers a structural solution to a universal problem: the gap between academic educational aspiration and company qualification needs. Simultaneous training in company and vocational school avoids the decoupling of theory and practice, generates applicable knowledge, and integrates young people directly into the labour market — which keeps youth unemployment permanently low.","options":["Das deutsche duale Ausbildungssystem gilt international als Erfolgsmodell, weil es eine strukturelle Lösung für ein universelles Problem bietet: die Lücke zwischen akademischem Bildungsanspruch und betrieblichem Qualifikationsbedarf. Die gleichzeitige Ausbildung in Betrieb und Berufsschule vermeidet die Entkoppelung von Theorie und Praxis, erzeugt anwendbares Wissen und integriert Jugendliche direkt in den Arbeitsmarkt — was Jugendarbeitslosigkeit dauerhaft niedrig hält.","Das duale System kombiniert Berufsschule und Betrieb — Theorie und Praxis in einem.","Deutschland hat niedrige Jugendarbeitslosigkeit, weil das duale System direkt in den Beruf führt.","Azubis lernen im Betrieb und in der Schule gleichzeitig — das ist besser als reines Studium."],"correctAnswer":"Das deutsche duale Ausbildungssystem gilt international als Erfolgsmodell, weil es eine strukturelle Lösung für ein universelles Problem bietet: die Lücke zwischen akademischem Bildungsanspruch und betrieblichem Qualifikationsbedarf. Die gleichzeitige Ausbildung in Betrieb und Berufsschule vermeidet die Entkoppelung von Theorie und Praxis, erzeugt anwendbares Wissen und integriert Jugendliche direkt in den Arbeitsmarkt — was Jugendarbeitslosigkeit dauerhaft niedrig hält."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Wahlergebnis spiegelt die wachsende Unzufriedenheit in der Bevölkerung ___.","options":["wider","ab","vor","auf"],"correctAnswer":"wider"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The wage differences between men and women reflect structural inequalities","wordBankItems":["Die","Lohnunterschiede","zwischen","Männern","und","Frauen","spiegeln","strukturelle","Ungleichheiten","wider","."],"correctAnswer":"Die Lohnunterschiede zwischen Männern und Frauen spiegeln strukturelle Ungleichheiten wider ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Handwerklich'' means?","options":["manual/craft-based","practical","artisanal","technical"],"correctAnswer":"manual/craft-based"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000030a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss university admissions and Numerus Clausus at B2","Use Hochschulzulassung und NC vocabulary","Talk about Germany''s NC system, Stiftung für Hochschulzulassung, and admissions fairness"],"explanation":{"intro":"University admissions vocabulary covers Germany''s NC system, the Hochschulstart platform, and debates about admissions fairness at B2.","culturalNote":"Hochschulzulassung und Numerus Clausus: Germany: NC (Numerus Clausus — restricted entry — based on Abitur grade + waiting time). Hochschulstart (DoSV — Dialogorientiertes Serviceverfahren — centralized admissions platform — replaced old ZVS). Stiftung für Hochschulzulassung (admissions foundation). Key NC subjects: Medizin (medicine — NC 1.0 historically — impossible), Psychologie, Jura (law — some NC), Lehramt. Bundesverfassungsgericht 2017: NC system for medicine was unconstitutional — new criteria from 2020: Abitur (51%), aptitude tests/interviews (30%), waiting time (20%). Zulassungsverfahren (admissions procedures — complex). Zulassung ohne NC (many subjects). Eignungstest (aptitude test — TMS Medizin, HAM-Nat). Abiturmittelwert (Abitur average — cut-off). Key tension: Abitur grades differ by state (Länder-Niveauunterschiede). Fair admission despite different Abitur standards."},"examples":[{"german":"Das Numerus-Clausus-System ist eine radikale Vereinfachung eines komplexen Auswahlproblems: Eine einzige Note — der Abiturmittelwert — entscheidet darüber, wer Zugang zu zulassungsbeschränkten Studiengängen erhält. Das Bundesverfassungsgericht hat 2017 festgestellt, dass dieses Verfahren für das Medizinstudium verfassungswidrig ist, weil es eine unverhältnismäßige Bedeutung einer einzigen Bewerbungskomponente beimisst und andere relevante Eignungsaspekte ausklammert.","english":"The numerus clausus system is a radical simplification of a complex selection problem: a single grade — the Abitur average — decides who gets access to admission-restricted degree programmes. The Federal Constitutional Court established in 2017 that this procedure for medical studies is unconstitutional, because it assigns disproportionate significance to a single application component and excludes other relevant aptitude aspects."},{"german":"Die Reform der Medizinzulassung nach dem Verfassungsgerichtsurteil zeigt, wie Bewerbungsverfahren Werte kodieren: Wer in medizinische Studiengänge zugelassen wird, hängt davon ab, was Universitäten für Eignungsmerkmale halten — Abiturnoten, Wartesemester, Interviews, fachspezifische Eignungstests — und diese Entscheidungen legen normativ fest, welche Art von Ärzten das System produzieren soll.","english":"The reform of medical admissions following the constitutional court ruling shows how application procedures encode values: who is admitted to medical degree programmes depends on what universities consider aptitude characteristics — Abitur grades, waiting semesters, interviews, subject-specific aptitude tests — and these decisions normatively determine what kind of doctors the system should produce."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Germany''s NC system, the medical admissions reform, and the politics of university admissions at B2."}}',
'{"items":[{"word":"zulassungsbeschränkt","translation":"admission-restricted","pronunciation":"tsoo-LAS-oongs-beh-shrenkjt","example":"Zulassungsbeschränktes Fach."},{"word":"der Eignungstest","translation":"aptitude test","pronunciation":"dayr EYK-noongs-test","example":"Fachspezifischer Eignungstest."},{"word":"der Abiturmittelwert","translation":"Abitur average","pronunciation":"dayr a-bi-TOOR-mit-el-vehrt","example":"Abiturmittelwert berechnen."},{"word":"ausklammern","translation":"to exclude/bracket out","pronunciation":"OWS-kla-mern","example":"Andere Aspekte ausklammern."},{"word":"beimessen","translation":"to assign/attribute (weight to)","pronunciation":"BY-mes-en","example":"Bedeutung beimessen."},{"word":"kodieren","translation":"to encode","pronunciation":"ko-DEE-ren","example":"Werte kodieren."}]}',
'{"title":"Etwas stellt fest, dass X — something establishes/determines that X","pattern":"etwas stellt fest, dass X = something establishes/determines that X (feststellen = to establish, determine, find — separable: stellt...fest; used when a court, study, authority makes an official determination — strong epistemic commitment)","explanation":"Feststellen = to establish, determine, find (separable: stellt...fest — fest = firm + stellen = to place; to firmly establish). Das Bundesverfassungsgericht hat festgestellt, dass X = the Federal Constitutional Court has established/found that X. Used for official determinations by courts, scientific studies, official bodies — marks a finding with authority. Compare: zeigen (to show — softer, less authoritative), nachweisen (to prove — evidence-based, more scientific), belegen (to demonstrate — documentation-based), konstatieren (to note, state — formal, but less authoritative than feststellen), beschließen (to decide — more decisional, less epistemic).","examples":[{"sentence":"Die Studie hat festgestellt, dass der Effekt statistisch signifikant ist.","translation":"The study has established that the effect is statistically significant."},{"sentence":"Die Kommission hat festgestellt, dass gegen das Protokoll verstoßen wurde.","translation":"The commission has established that the protocol was violated."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Ausklammern'' means?","options":["to exclude/bracket out","to omit","to ignore","to set aside"],"correctAnswer":"to exclude/bracket out"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The numerus clausus system is a radical simplification of a complex selection problem: a single grade — the Abitur average — decides who gets access to admission-restricted degree programmes. The Federal Constitutional Court established in 2017 that this procedure for medical studies is unconstitutional, because it assigns disproportionate significance to a single application component and excludes other relevant aptitude aspects.","options":["Das Numerus-Clausus-System ist eine radikale Vereinfachung eines komplexen Auswahlproblems: Eine einzige Note — der Abiturmittelwert — entscheidet darüber, wer Zugang zu zulassungsbeschränkten Studiengängen erhält. Das Bundesverfassungsgericht hat 2017 festgestellt, dass dieses Verfahren für das Medizinstudium verfassungswidrig ist, weil es eine unverhältnismäßige Bedeutung einer einzigen Bewerbungskomponente beimisst und andere relevante Eignungsaspekte ausklammert.","Das NC-System ist ungerecht, weil eine Note nicht über Studierfähigkeit entscheidet.","Das Verfassungsgericht hat entschieden, dass der NC für Medizin verfassungswidrig ist.","Ein einziger Abiturmittelwert kann nicht alle relevanten Aspekte der Eignung erfassen."],"correctAnswer":"Das Numerus-Clausus-System ist eine radikale Vereinfachung eines komplexen Auswahlproblems: Eine einzige Note — der Abiturmittelwert — entscheidet darüber, wer Zugang zu zulassungsbeschränkten Studiengängen erhält. Das Bundesverfassungsgericht hat 2017 festgestellt, dass dieses Verfahren für das Medizinstudium verfassungswidrig ist, weil es eine unverhältnismäßige Bedeutung einer einzigen Bewerbungskomponente beimisst und andere relevante Eignungsaspekte ausklammert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Kommission hat festgestellt, dass gegen das Protokoll verstoßen ___.","options":["wurde","war","ist","wird"],"correctAnswer":"wurde"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The study has established that the effect is statistically significant","wordBankItems":["Die","Studie","hat","festgestellt",",","dass","der","Effekt","statistisch","signifikant","ist","."],"correctAnswer":"Die Studie hat festgestellt , dass der Effekt statistisch signifikant ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kodieren'' means?","options":["to encode","to programme","to embed","to inscribe"],"correctAnswer":"to encode"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000030b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss education and democracy at B2","Use Bildung und Demokratie vocabulary","Talk about political education, civic literacy, and democracy as a learning process"],"explanation":{"intro":"Education and democracy vocabulary covers political education, Beutelsbacher Konsens, and democratic civic literacy at B2.","culturalNote":"Bildung und Demokratie: Germany: Politische Bildung (political education — especially important post-1945 after Nazi education failure). Beutelsbacher Konsens (1976 — three principles for political education: Überwältigungsverbot = no indoctrination; Kontroversitätsgebot = controversial issues must be taught as controversial; Schülerorientierung = student must be enabled to form own political views). BpB (Bundeszentrale für politische Bildung — Federal Agency for Civic Education — journals, materials, election programs). LpB (Landeszentralen). Politikunterricht (politics/civics class — not mandatory everywhere). Demokratiepädagogik (democracy pedagogy). Wahlrecht ab 16 (voting from 16 in some states for state elections). Jugendparlamente (youth parliaments). Key concept: Hannah Arendt — Bildung als Einführung in die Welt = education as introduction to the world. Civic literacy. Key challenge: Wahlbeteiligung bei jungen Menschen (youth voter turnout)."},"examples":[{"german":"Der Beutelsbacher Konsens definiert die Grenzen staatlicher politischer Bildung in einer Demokratie: Politische Bildung darf nicht zur Indoktrination werden — sie muss kontroverses politisch als kontrovers darstellen und Schüler dazu befähigen, sich eine eigene fundierte Meinung zu bilden, nicht eine vorgefertigte zu übernehmen. Dieses Gleichgewicht zwischen staatlicher Wertevermittlung und individueller Urteilsbildung ist konstitutiv für demokratische Bildung.","english":"The Beutelsbacher Consensus defines the limits of state political education in a democracy: political education must not become indoctrination — it must present what is politically controversial as controversial, and enable pupils to form their own informed opinion, not to adopt a ready-made one. This balance between state transmission of values and individual judgment formation is constitutive for democratic education."},{"german":"Demokratie braucht demokratisch gebildete Bürgerinnen und Bürger: Die Fähigkeit, politische Informationen kritisch zu beurteilen, Meinungen zu begründen, Kompromisse auszuhandeln und demokratische Institutionen zu verstehen, ist keine angeborene Fähigkeit, sondern muss gelernt werden — ein Argument für politische Bildung als unverzichtbaren Bestandteil des öffentlichen Bildungssystems in einer pluralistischen Gesellschaft.","english":"Democracy needs democratically educated citizens: the ability to critically assess political information, substantiate opinions, negotiate compromises, and understand democratic institutions is not an innate ability, but must be learned — an argument for political education as an indispensable part of the public education system in a pluralistic society."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the Beutelsbacher Konsens, political education in Germany, and the relationship between education and democracy at B2."}}',
'{"items":[{"word":"die Indoktrination","translation":"indoctrination","pronunciation":"dee in-dok-tri-na-TSYOHN","example":"Indoktrination vermeiden."},{"word":"konstitutiv","translation":"constitutive","pronunciation":"kon-sti-too-TEEF","example":"Konstitutiv für Demokratie."},{"word":"die Urteilsbildung","translation":"judgment formation","pronunciation":"dee oor-TYLS-bil-doong","example":"Individuelle Urteilsbildung."},{"word":"begründen","translation":"to substantiate/justify","pronunciation":"beh-GRÜN-den","example":"Meinungen begründen."},{"word":"unverzichtbar","translation":"indispensable","pronunciation":"oon-fer-TSIKHT-bar","example":"Unverzichtbarer Bestandteil."},{"word":"aushandeln","translation":"to negotiate","pronunciation":"OWS-han-deln","example":"Kompromisse aushandeln."}]}',
'{"title":"Etwas darf nicht zu X werden — something must not become X","pattern":"etwas darf nicht zu X werden = something must not become X (darf nicht = is not permitted to, must not — dürfen + nicht = prohibition; zu X werden = to become X — marks a normative boundary: X is the forbidden outcome)","explanation":"Dürfen + nicht = must not (darf = is permitted — darf nicht = is not permitted = must not; stronger than soll nicht). Zu X werden = to become X (werden = to become). Etwas darf nicht zu Indoktrination werden = something must not become indoctrination. The pattern marks a normative red line — X is not just undesirable but impermissible. Compare: soll nicht (should not — weaker, more prescriptive), muss vermieden werden (must be avoided — more active), ist verboten (is forbidden — legal context), darf unter keinen Umständen (must under no circumstances — stronger absolute prohibition).","examples":[{"sentence":"Kritische Theorie darf nicht zu einer neuen Orthodoxie werden.","translation":"Critical theory must not become a new orthodoxy."},{"sentence":"Sicherheitsgesetze dürfen nicht zur Aushöhlung von Grundrechten werden.","translation":"Security laws must not become the hollowing out of fundamental rights."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Konstitutiv'' means?","options":["constitutive","fundamental","essential","formative"],"correctAnswer":"constitutive"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Beutelsbacher Consensus defines the limits of state political education in a democracy: political education must not become indoctrination — it must present what is politically controversial as controversial, and enable pupils to form their own informed opinion, not to adopt a ready-made one. This balance between state transmission of values and individual judgment formation is constitutive for democratic education.","options":["Der Beutelsbacher Konsens definiert die Grenzen staatlicher politischer Bildung in einer Demokratie: Politische Bildung darf nicht zur Indoktrination werden — sie muss kontroverses politisch als kontrovers darstellen und Schüler dazu befähigen, sich eine eigene fundierte Meinung zu bilden, nicht eine vorgefertigte zu übernehmen. Dieses Gleichgewicht zwischen staatlicher Wertevermittlung und individueller Urteilsbildung ist konstitutiv für demokratische Bildung.","Politische Bildung muss neutral sein und darf keine bestimmte politische Meinung vermitteln.","Der Beutelsbacher Konsens schützt Schüler vor politischer Beeinflussung im Unterricht.","Gute politische Bildung zeigt Kontroversen als Kontroversen und fördert eigenes Denken."],"correctAnswer":"Der Beutelsbacher Konsens definiert die Grenzen staatlicher politischer Bildung in einer Demokratie: Politische Bildung darf nicht zur Indoktrination werden — sie muss kontroverses politisch als kontrovers darstellen und Schüler dazu befähigen, sich eine eigene fundierte Meinung zu bilden, nicht eine vorgefertigte zu übernehmen. Dieses Gleichgewicht zwischen staatlicher Wertevermittlung und individueller Urteilsbildung ist konstitutiv für demokratische Bildung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sicherheitsgesetze dürfen nicht zur Aushöhlung von Grundrechten ___.","options":["werden","sein","führen","gelten"],"correctAnswer":"werden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Critical theory must not become a new orthodoxy","wordBankItems":["Kritische","Theorie","darf","nicht","zu","einer","neuen","Orthodoxie","werden","."],"correctAnswer":"Kritische Theorie darf nicht zu einer neuen Orthodoxie werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aushandeln'' means?","options":["to negotiate","to bargain","to compromise","to mediate"],"correctAnswer":"to negotiate"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000030c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss the competence society at B2","Use Kompetenzgesellschaft vocabulary","Talk about the shift from knowledge to competence, skills-based society, and 21st century skills"],"explanation":{"intro":"Competence society vocabulary covers the shift from knowledge-based to competence-based education, 21st century skills, and the OECD Learning Framework at B2.","culturalNote":"Kompetenzgesellschaft: Key shift: late 20th century — from Wissensgesellschaft (knowledge society) to Kompetenzgesellschaft (competence society — the issue is not just what you know but what you can do with it). Key: OECD DeSeCo (Definition and Selection of Competencies — 1997-2003 — three key competencies: using tools interactively, interacting in heterogeneous groups, acting autonomously). 21st century skills (4Cs: Critical Thinking, Creativity, Collaboration, Communication). Key: PISA measures competence, not content knowledge. Kompetenzorientierung in Lehrplänen (competence orientation in curricula — shift away from Lernstoff). Key tension: Bildung (classical German concept — formation of the whole person — Humboldt) vs. Kompetenzen (skills/abilities — employability-oriented). Schlüsselkompetenzen (key competencies). Employability. Problem-based learning. Portfolio assessment vs. standardised tests. Informelles Lernen (informal learning). OECD Future of Education and Skills 2030. Zukunftskompetenzen (future competencies — AI literacy, data literacy, sustainability literacy)."},"examples":[{"german":"Die Verschiebung von der Wissens- zur Kompetenzgesellschaft hat tiefgreifende Konsequenzen für Bildungskonzeptionen: Wenn nicht mehr der Besitz von Wissen, sondern die Fähigkeit, Wissen anzuwenden, Probleme zu lösen und in unbekannten Situationen zu handeln, zentral ist, dann verändert das die Rolle von Bildungseinrichtungen — von Wissensspeichern zu Kompetenzentwicklern. Dieser Wandel ist nicht ohne Spannung: das humanistische Bildungsideal der Allgemeinbildung gerät in Konflikt mit einer funktionalistischen Kompetenzorientierung.","english":"The shift from the knowledge society to the competence society has profound consequences for educational concepts: if it is no longer the possession of knowledge but the ability to apply knowledge, solve problems, and act in unfamiliar situations that is central, then this changes the role of educational institutions — from knowledge repositories to competence developers. This change is not without tension: the humanist ideal of general education comes into conflict with a functionalist competence orientation."},{"german":"Das Paradox der Kompetenzorientierung liegt in ihrer Messproblematik: Kompetenzen sind definitionsgemäß kontextgebundene Handlungsfähigkeiten — sie zeigen sich in situativen Anwendungen, nicht in isolierten Tests. Standardisierte Kompetenzerhebungen wie PISA messen deshalb notwendigerweise Proxies, nicht die Kompetenzen selbst — eine methodologische Einschränkung, die zu überinterpretierten Rangfolgen und Policy-Konsequenzen führt, die auf Sand gebaut sind.","english":"The paradox of competence orientation lies in its measurement problem: competencies are by definition context-bound action capabilities — they manifest themselves in situational applications, not in isolated tests. Standardised competence surveys like PISA therefore necessarily measure proxies, not the competencies themselves — a methodological limitation that leads to over-interpreted rankings and policy consequences built on sand."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the competence society, 21st century skills, and the tension between Bildung and Kompetenzen at B2."}}',
'{"items":[{"word":"die Kompetenz","translation":"competence/competency","pronunciation":"dee kom-peh-TENTS","example":"Schlüsselkompetenzen entwickeln."},{"word":"kontextgebunden","translation":"context-bound","pronunciation":"kon-TEXT-geh-boon-den","example":"Kontextgebundene Fähigkeiten."},{"word":"der Proxy","translation":"proxy","pronunciation":"dayr PROK-see","example":"Proxies messen statt echter Kompetenzen."},{"word":"die Einschränkung","translation":"limitation/constraint","pronunciation":"dee EYN-shrenk-oong","example":"Methodologische Einschränkung."},{"word":"definitionsgemäß","translation":"by definition","pronunciation":"deh-fi-ni-TSYOHNS-geh-mäss","example":"Definitionsgemäß kontextgebunden."},{"word":"überinterpretieren","translation":"to over-interpret","pronunciation":"ü-ber-in-ter-preh-TEE-ren","example":"Ergebnisse überinterpretieren."}]}',
'{"title":"X liegt in Y — X lies in Y (the core of X is Y)","pattern":"das Paradox von X liegt in Y = the paradox of X lies in Y (liegen in = to lie in, consist in — marks where the essential nature, core problem, or contradiction of X is located — not physical but conceptual location)","explanation":"Liegen in = to lie in, consist in, be found in (conceptual — not physical location). Das Paradox liegt in der Messproblematik = the paradox lies in the measurement problem (the measurement problem is where the paradox is located). The pattern locates the essence, core tension, or root cause of X in Y — not outside X but within it. Compare: bestehen in (to consist in — similar, more stative), sich zeigen in (to manifest in — more visible), seinen Ursprung haben in (to have its origin in — more causal/historical), wurzeln in (to be rooted in — more deep, structural).","examples":[{"sentence":"Das Problem liegt nicht in der Technologie, sondern in ihrer Anwendung.","translation":"The problem lies not in the technology, but in its application."},{"sentence":"Die Stärke dieser Theorie liegt in ihrer Falsifizierbarkeit.","translation":"The strength of this theory lies in its falsifiability."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Kontextgebunden'' means?","options":["context-bound","situational","context-dependent","circumstantial"],"correctAnswer":"context-bound"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The shift from the knowledge society to the competence society has profound consequences for educational concepts: if it is no longer the possession of knowledge but the ability to apply knowledge, solve problems, and act in unfamiliar situations that is central, then this changes the role of educational institutions — from knowledge repositories to competence developers. This change is not without tension: the humanist ideal of general education comes into conflict with a functionalist competence orientation.","options":["Die Verschiebung von der Wissens- zur Kompetenzgesellschaft hat tiefgreifende Konsequenzen für Bildungskonzeptionen: Wenn nicht mehr der Besitz von Wissen, sondern die Fähigkeit, Wissen anzuwenden, Probleme zu lösen und in unbekannten Situationen zu handeln, zentral ist, dann verändert das die Rolle von Bildungseinrichtungen — von Wissensspeichern zu Kompetenzentwicklern. Dieser Wandel ist nicht ohne Spannung: das humanistische Bildungsideal der Allgemeinbildung gerät in Konflikt mit einer funktionalistischen Kompetenzorientierung.","In der Kompetenzgesellschaft zählt nicht, was man weiß, sondern was man damit macht.","Bildung verändert sich: Statt Wissensvermittlung steht Kompetenzentwicklung im Vordergrund.","Die Fähigkeit, Probleme zu lösen und in neuen Situationen zu handeln, ist heute wichtiger als reines Wissen."],"correctAnswer":"Die Verschiebung von der Wissens- zur Kompetenzgesellschaft hat tiefgreifende Konsequenzen für Bildungskonzeptionen: Wenn nicht mehr der Besitz von Wissen, sondern die Fähigkeit, Wissen anzuwenden, Probleme zu lösen und in unbekannten Situationen zu handeln, zentral ist, dann verändert das die Rolle von Bildungseinrichtungen — von Wissensspeichern zu Kompetenzentwicklern. Dieser Wandel ist nicht ohne Spannung: das humanistische Bildungsideal der Allgemeinbildung gerät in Konflikt mit einer funktionalistischen Kompetenzorientierung."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Stärke dieser Theorie liegt in ihrer ___.","options":["Falsifizierbarkeit","Stärke","Konzeption","Methode"],"correctAnswer":"Falsifizierbarkeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The problem lies not in the technology but in its application","wordBankItems":["Das","Problem","liegt","nicht","in","der","Technologie",",","sondern","in","ihrer","Anwendung","."],"correctAnswer":"Das Problem liegt nicht in der Technologie , sondern in ihrer Anwendung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Definitionsgemäß'' means?","options":["by definition","definitionally","per definition","as defined"],"correctAnswer":"by definition"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

